//
//  ReadingTable.swift
//  Easydict
//
//  Slim build: read-only lookup over a bundled reading dictionary generated by
//  scripts/reading-dict/update.sh (LZFSE-compressed TSV, rows sorted by key).
//

import Foundation

// MARK: - ReadingTable

/// Keeps the decompressed rows as one byte buffer plus row offsets and binary-searches the
/// first field, so hundreds of thousands of entries cost little more than their text size.
final class ReadingTable: Sendable {
    // MARK: Lifecycle

    /// Loads `<name>.tsv.lzfse` from the app bundle. A missing or corrupt resource yields an
    /// empty table (and is logged), so lookups simply find nothing.
    init(resourceName name: String) {
        guard let url = Bundle.main.url(forResource: "\(name).tsv", withExtension: "lzfse"),
              let compressed = try? Data(contentsOf: url),
              let data = try? (compressed as NSData).decompressed(using: .lzfse) as Data
        else {
            logError("Reading dictionary \(name) is missing or unreadable")
            self.bytes = []
            self.rowStarts = []
            return
        }

        let bytes = [UInt8](data)
        var rowStarts: [Int32] = []
        rowStarts.reserveCapacity(bytes.count / 16)
        var rowStart = 0
        for (index, byte) in bytes.enumerated() where byte == Self.newline {
            if index > rowStart {
                rowStarts.append(Int32(rowStart))
            }
            rowStart = index + 1
        }
        self.bytes = bytes
        self.rowStarts = rowStarts
    }

    // MARK: Internal

    /// Everything after the first tab of each row whose first field equals `key`, in file order.
    func values(for key: String) -> [String] {
        let target = Array(key.utf8)
        var low = 0
        var high = rowStarts.count
        while low < high {
            let middle = (low + high) / 2
            if compareKey(row: middle, with: target) < 0 {
                low = middle + 1
            } else {
                high = middle
            }
        }

        var values: [String] = []
        var row = low
        while row < rowStarts.count, compareKey(row: row, with: target) == 0 {
            values.append(value(row: row, keyLength: target.count))
            row += 1
        }
        return values
    }

    // MARK: Private

    private static let newline = UInt8(ascii: "\n")
    private static let tab = UInt8(ascii: "\t")

    private let bytes: [UInt8]
    private let rowStarts: [Int32]

    /// Compares the first field of `row` with `target` in UTF-8 byte order.
    private func compareKey(row: Int, with target: [UInt8]) -> Int {
        var position = Int(rowStarts[row])
        for byte in target {
            guard position < bytes.count else { return -1 }
            let current = bytes[position]
            if current == Self.tab || current == Self.newline || current < byte {
                return -1
            }
            if current > byte {
                return 1
            }
            position += 1
        }
        guard position < bytes.count else { return 0 }
        let next = bytes[position]
        return next == Self.tab || next == Self.newline ? 0 : 1
    }

    private func value(row: Int, keyLength: Int) -> String {
        let separator = Int(rowStarts[row]) + keyLength
        guard separator < bytes.count, bytes[separator] == Self.tab else { return "" }
        let start = separator + 1
        var end = start
        while end < bytes.count, bytes[end] != Self.newline {
            end += 1
        }
        guard start < end else { return "" }
        return String(bytes: bytes[start ..< end], encoding: .utf8) ?? ""
    }
}
